import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Key, Copy, Check, AlertTriangle } from 'lucide-react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import toast from 'react-hot-toast';
import salesRepService from '../../services/salesRepService';

const PasswordResetModal = ({ isOpen, onClose, salesRep }) => {
    const [newPassword, setNewPassword] = useState(null);
    const [copied, setCopied] = useState(false);
    const queryClient = useQueryClient();

    const resetMutation = useMutation({
        mutationFn: () => salesRepService.resetPassword(salesRep.id),
        onSuccess: (data) => {
            setNewPassword(data.data.newPassword);
            toast.success('Password reset successfully');
            queryClient.invalidateQueries(['sales-reps']);
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Failed to reset password');
        }
    });

    const copyPassword = () => {
        navigator.clipboard.writeText(newPassword);
        setCopied(true);
        toast.success('Password copied!');
        setTimeout(() => setCopied(false), 2000);
    };

    const handleClose = () => {
        setNewPassword(null);
        setCopied(false);
        onClose();
    };

    return (
        <AnimatePresence>
            {isOpen && salesRep && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-black/50 backdrop-blur-sm"
                        onClick={handleClose}
                    />

                    <motion.div
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.95 }}
                        className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-md p-6"
                    >
                        <div className="flex items-start justify-between mb-4">
                            <div className="flex items-center gap-2">
                                <Key className="h-5 w-5 text-amber-600" />
                                <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                                    Reset Password
                                </h3>
                            </div>
                            <button
                                onClick={handleClose}
                                className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
                            >
                                <X className="h-5 w-5 text-gray-500" />
                            </button>
                        </div>

                        <p className="text-gray-500 dark:text-gray-400 mb-4">
                            Reset password for <strong>{salesRep.firstName} {salesRep.lastName}</strong> ({salesRep.email})
                        </p>

                        {!newPassword ? (
                            <>
                                <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg mb-4">
                                    <div className="flex items-start gap-2">
                                        <AlertTriangle className="h-5 w-5 text-amber-600 flex-shrink-0 mt-0.5" />
                                        <p className="text-sm text-amber-800 dark:text-amber-400">
                                            This will generate a new secure password. The old password will no longer work.
                                        </p>
                                    </div>
                                </div>

                                <div className="flex gap-3">
                                    <button
                                        onClick={handleClose}
                                        className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        onClick={() => resetMutation.mutate()}
                                        disabled={resetMutation.isLoading}
                                        className="flex-1 px-4 py-2 bg-amber-600 hover:bg-amber-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50"
                                    >
                                        {resetMutation.isLoading ? 'Resetting...' : 'Reset Password'}
                                    </button>
                                </div>
                            </>
                        ) : (
                            <>
                                <div className="p-4 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800 rounded-lg mb-4">
                                    <p className="text-sm text-emerald-800 dark:text-emerald-400 font-medium mb-2">
                                        New password generated:
                                    </p>
                                    <div className="flex items-center gap-2">
                                        <input
                                            type="text"
                                            value={newPassword}
                                            readOnly
                                            className="flex-1 px-3 py-2 bg-white dark:bg-gray-900 border border-emerald-200 dark:border-emerald-800 rounded-lg text-sm font-mono"
                                        />
                                        <button
                                            onClick={copyPassword}
                                            className="p-2 hover:bg-emerald-100 dark:hover:bg-emerald-900/40 rounded-lg transition-colors"
                                        >
                                            {copied ? (
                                                <Check className="h-4 w-4 text-emerald-600" />
                                            ) : (
                                                <Copy className="h-4 w-4 text-emerald-600" />
                                            )}
                                        </button>
                                    </div>
                                </div>

                                <button
                                    onClick={handleClose}
                                    className="w-full px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors"
                                >
                                    Done
                                </button>
                            </>
                        )}
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    );
};

export default PasswordResetModal;
